<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { CarFront, Crosshair, Layers, RefreshCw, Search, X } from 'lucide-vue-next';
import { api } from '../api';import { useSessionStore } from '../stores/session';
import QueryPanel from '../components/QueryPanel.vue';import QueryField from '../components/QueryField.vue';import OperationsMap from '../components/OperationsMap.vue';
import VehicleDetailDrawer from '../components/VehicleDetailDrawer.vue';import PermitDetailDrawer from '../components/PermitDetailDrawer.vue';
import { admissionDate, can, permitStates, permitTypes } from '../admission';import { subjectError } from '../subject-management';
import { ageText, drivingMode, monitorStates, monitorTime } from '../operations-supervision';import '../operations-supervision.css';
const session=useSessionStore(),route=useRoute(),router=useRouter(),user=computed(()=>session.user),enterprise=computed(()=>user.value?.portal==='ENTERPRISE');
const filters=reactive({q:String(route.query.q??''),enterpriseId:String(route.query.enterpriseId??''),drivingState:String(route.query.drivingState??''),permitStatus:String(route.query.permitStatus??'')});let applied={...filters};
const items=ref<any[]>([]),options=ref<any>({enterprises:[]}),summary=ref<any>({total:0,running:0,parked:0,offline:0,abnormal:0}),updatedAt=ref(''),concentrated=ref<any[]>([]),view=ref(String(route.query.listView??'all'));
const selectedId=ref(String(route.query.vehicleId??'')),detailOpen=ref(true),tab=ref(String(route.query.tab??'state')),loading=ref(false),loaded=ref(false),error=ref(''),refreshError=ref(''),optionError=ref(''),mapRef=ref<any>();
const showRegions=ref(true),showFences=ref(false),fences=ref<any[]>([]),fenceError=ref(''),archiveOpen=ref(false),permitOpen=ref(false);
const pageRoot=ref<HTMLElement|null>(null);
const selected=computed(()=>items.value.find(v=>v.id===selectedId.value));
const regionRows=computed<any[]>(()=>{const values=new Map<string,any>();for(const v of items.value)if(['VALID','EXPIRING'].includes(v.permit?.status))for(const r of v.permit.conditions.regions??[])if(r.polygon?.length>=3)values.set(r.id,{...r,status:'ACTIVE',regionType:'OPERATION'});return [...values.values()]});
let request=0,controller:AbortController|undefined,timer:number|undefined,trackGeneration=0,recordGeneration=0;
const track=ref<any[]>([]),trackLoading=ref(false),trackError=ref(''),trackRange=ref<any>(null),trackTruncated=ref(false),records=ref<any[]>([]),recordTotal=ref(0),recordPage=ref(1),recordError=ref(''),recordLoading=ref(false),playing=ref(false),paused=ref(false);
const displayIssues=computed(()=>selected.value?.issues.filter((i:any)=>!selected.value.alerts.some((a:any)=>a.alertType===i.type))??[]);
const hasTrack=computed(()=>tab.value==='track'&&detailOpen.value),hasAlertPermission=computed(()=>can(user.value,'safety:alert:read'));
const stats=computed(()=>({count:track.value.length,max:track.value.length?Math.max(...track.value.map(p=>p.speed)):null}));
function syncRoute(){const q:any={...applied};for(const k of Object.keys(q))if(!q[k])delete q[k];if(selectedId.value)q.vehicleId=selectedId.value;if(view.value!=='all')q.listView=view.value;if(tab.value!=='state')q.tab=tab.value;router.replace({path:route.path,query:q})}
async function load(silent=false){if(silent&&loading.value)return;const n=++request;controller?.abort();controller=new AbortController();if(!silent)loading.value=true;try{const p=new URLSearchParams(applied);if(view.value==='abnormal')p.set('view','abnormal');const data=await api<any>(`/operations/realtime?${p}`,{signal:controller.signal});if(n!==request)return;items.value=data.items;summary.value=data.summary;concentrated.value=data.concentrated??[];updatedAt.value=data.updatedAt;error.value='';refreshError.value='';loaded.value=true;if(!items.value.some(v=>v.id===selectedId.value)){selectedId.value=items.value[0]?.id??'';tab.value='state'}syncRoute()}catch(e){if(n===request){if(loaded.value)refreshError.value=subjectError(e);else error.value=subjectError(e)}}finally{if(n===request)loading.value=false}}
async function loadOptions(){try{options.value=await api('/operations/options');optionError.value=''}catch(e){optionError.value=subjectError(e)}}
function search(){applied={...filters};return load()}
function reset(){Object.assign(filters,{q:'',enterpriseId:'',drivingState:'',permitStatus:''});view.value='all';search()}
function choose(v:any){selectedId.value=v.id;detailOpen.value=true;tab.value='state';syncRoute()}
function chooseMap(id:string){const row=items.value.find(v=>v.id===id);if(row)choose(row)}
function toggleView(v:string){view.value=v;load()}
function dateDefaults(){const end=new Date(),start=new Date(end);start.setHours(0,0,0,0);return [start.toISOString(),end.toISOString()]}
async function loadTrack(){if(!selected.value)return;const n=++trackGeneration;trackLoading.value=true;trackError.value='';playing.value=false;paused.value=false;try{const range=trackRange.value??dateDefaults(),p=new URLSearchParams({from:range[0],to:range[1]});const d=await api<any>(`/operations/vehicles/${selectedId.value}/tracks?${p}`);if(n===trackGeneration){track.value=d.points;trackTruncated.value=d.truncated}}catch(e){if(n===trackGeneration){track.value=[];trackError.value=subjectError(e)}}finally{if(n===trackGeneration)trackLoading.value=false}}
async function loadRecords(){if(!selected.value)return;const n=++recordGeneration;recordLoading.value=true;recordError.value='';try{const d=await api<any>(`/operations/records?vehicleId=${selectedId.value}&page=${recordPage.value}&pageSize=10`);if(n===recordGeneration){records.value=d.items;recordTotal.value=d.total}}catch(e){if(n===recordGeneration){records.value=[];recordError.value=subjectError(e)}}finally{if(n===recordGeneration)recordLoading.value=false}}
watch(tab,()=>{trackGeneration++;recordGeneration++;playing.value=false;if(tab.value==='track'){trackRange.value=dateDefaults();loadTrack()}if(tab.value==='records'){recordPage.value=1;loadRecords()}syncRoute()});
watch(selectedId,()=>{nextTick(()=>pageRoot.value?.querySelector('[data-vehicle-id="'+selectedId.value+'"]')?.scrollIntoView({block:'nearest'}));trackGeneration++;recordGeneration++;track.value=[];records.value=[];recordTotal.value=0;playing.value=false});watch(recordPage,loadRecords);
async function loadFences(){if(!showFences.value)return;fenceError.value='';try{const rows:any[]=[];for(let page=1;;page++){const d=await api<any>(`/safety/fences?status=ACTIVE&page=${page}&pageSize=100`);rows.push(...d.items.filter((f:any)=>f.fenceType!=='OPERATION'));if(d.items.length<100||page*100>=d.total)break}fences.value=rows}catch(e){fenceError.value=subjectError(e);showFences.value=false}}
watch(showFences,loadFences);
function event(id:string){router.push({path:enterprise.value?'/enterprise/safety/events':'/safety/events',query:{view:'ALERT',eventId:id}})}
function allRecords(){router.push({path:route.path,query:{view:'records'}})}
function recordTrack(row:any){router.push({path:route.path,query:{view:'trajectory',vehicleId:selectedId.value,recordId:row.id}})}
function mapAction(action:string,id:string){chooseMap(id);if(action==='trajectory')tab.value='track';else if(action==='archive'&&can(user.value,'archive:vehicle:read'))archiveOpen.value=true;else if(action==='alerts'&&selected.value?.alerts?.[0])event(selected.value.alerts[0].id)}
async function focusMap(){await nextTick();mapRef.value?.fitVisible()}
function play(){if(playing.value&&paused.value){mapRef.value?.resumeTrack();paused.value=false}else{mapRef.value?.playTrack();playing.value=true;paused.value=false}}
function pause(){mapRef.value?.pauseTrack();paused.value=true}function stop(){mapRef.value?.stopTrack();playing.value=false;paused.value=false}
onMounted(async()=>{await Promise.all([load(),loadOptions()]);timer=window.setInterval(()=>{if(!document.hidden&&tab.value==='state'&&!archiveOpen.value&&!permitOpen.value)load(true)},10000)});
onBeforeUnmount(()=>{request++;trackGeneration++;recordGeneration++;controller?.abort();clearInterval(timer)});
</script>
<template>
<section ref="pageRoot" class="city-subject-page operations-supervision-page" aria-label="运行监测">
 <QueryPanel class="subject-query subject-query--vehicles" :loading="loading" @search="search" @reset="reset">
  <QueryField label="关键词" keyword><el-input v-model="filters.q" :prefix-icon="Search" clearable placeholder="搜索车辆名称或统一编码" aria-label="搜索监测车辆"/></QueryField>
  <QueryField v-if="!enterprise" label="企业"><el-select v-model="filters.enterpriseId" clearable filterable placeholder="全部企业" aria-label="监测企业"><el-option v-for="e in options.enterprises" :key="e.id" :label="e.name" :value="e.id"/></el-select></QueryField>
  <QueryField label="运行状态"><el-select v-model="filters.drivingState" clearable placeholder="全部状态" aria-label="监测运行状态"><el-option label="运行中" value="RUNNING"/><el-option label="在线临停 / 停驶" value="PARKED"/><el-option label="离线" value="OFFLINE"/></el-select></QueryField>
  <QueryField label="许可状态"><el-select v-model="filters.permitStatus" clearable placeholder="全部许可状态" aria-label="监测许可状态"><el-option v-for="(label,key) in {...permitStates,NONE:'未登记许可'}" :key="key" :label="label" :value="key"/></el-select></QueryField>
 </QueryPanel>
 <section class="subject-list monitor-shell" aria-label="运行监测结果">
  <header class="subject-list-header"><h2>运行监测 <span class="subject-count">{{loaded?items.length:'—'}}</span></h2><div class="subject-tools"><el-button v-if="can(user,'operation:record:read')" @click="allRecords">运行记录</el-button><span class="monitor-updated" v-if="updatedAt">更新于 {{new Date(updatedAt).toLocaleTimeString('zh-CN',{hour12:false})}} · 10秒刷新</span><el-button :icon="RefreshCw" :loading="loading" @click="load()">刷新</el-button><el-button v-if="!detailOpen&&selected" @click="detailOpen=true">车辆详情</el-button></div></header>
  <div v-if="refreshError" class="subject-inline-error" role="alert">更新失败，正在显示上次数据：{{refreshError}}<el-button link @click="load()">重试</el-button></div>
  <div v-if="optionError" class="subject-inline-error" role="alert">筛选选项加载失败 <el-button link @click="loadOptions">重试</el-button></div>
  <div v-if="error" class="subject-error" role="alert"><strong>运行监测暂时无法加载</strong><span>{{error}}</span><el-button @click="load()">重试</el-button></div><el-skeleton v-else-if="!loaded" :rows="12" animated/>
  <div v-else class="monitor-grid" :class="{'no-detail':!detailOpen||!selected}">
   <aside class="monitor-rail" aria-label="车辆列表"><div class="monitor-rail-head"><strong>车辆列表</strong><button :class="{active:view==='all'}" @click="toggleView('all')">全部 {{summary.total}}</button><button :class="{active:view==='abnormal'}" @click="toggleView('abnormal')">异常 {{summary.abnormal}}</button></div><div class="monitor-summary"><span>运行 {{summary.running}}</span><span>临停 {{summary.parked}}</span><span>离线 {{summary.offline}}</span></div><div class="monitor-vehicles"><p v-if="!items.length" class="subject-error">暂无符合条件的车辆</p>
    <button v-for="v in items" :key="v.id" class="monitor-row" :data-vehicle-id="v.id" :class="{active:selectedId===v.id}" :aria-label="`${v.name}监测详情`" :aria-pressed="selectedId===v.id" @click="choose(v)"><span class="monitor-car" :class="[v.health.state.toLowerCase(),{abnormal:v.alerts.length>0||v.issues.some((i:any)=>!['DATA_STALE','LOCATION_STALE'].includes(i.type))}]"><CarFront :size="17"/></span><span class="monitor-row-main"><strong>{{v.name}}</strong><small>{{v.unifiedCode||v.businessNo}}</small><small>{{v.enterprise.name}}</small></span><span class="monitor-row-state"><el-tag size="small" :type="v.health.stale?'info':v.health.state==='RUNNING'?'primary':'success'">{{monitorStates[v.health.state]}}</el-tag><span v-if="v.health.stale">{{ageText(v.health.heartbeatAge)}}</span><span v-else>{{v.realtimeStatus?.speed??'—'}} km/h</span></span></button>
   </div></aside>
   <div class="monitor-map"><div v-if="!items.length" class="monitor-map-empty" role="status">暂无符合条件的车辆，可调整查询条件</div><OperationsMap ref="mapRef" monitoring :mode="hasTrack?'trajectory':'realtime'" :points="hasTrack?[]:items" :track="hasTrack?track:[]" :regions="showRegions?regionRows:[]" :fences="showFences?fences:[]" :selected-id="selectedId" height="100%" @select="chooseMap" @action="mapAction" @ready="focusMap"/>
    <div class="monitor-map-notice" v-if="concentrated.length&&!hasTrack">{{concentrated[0].name}}等 {{concentrated.length}} 家企业集中上报超时，原因待核查</div>
    <div class="monitor-layers"><el-popover placement="bottom-end" trigger="click" :width="190"><template #reference><el-button size="small" :icon="Layers">图层</el-button></template><el-checkbox v-model="showRegions">许可通行范围</el-checkbox><el-checkbox v-if="can(user,'safety:fence:read')" v-model="showFences">电子围栏</el-checkbox><p v-if="!regionRows.length" class="monitor-note">当前许可未登记可显示的范围</p><p v-if="fenceError" role="alert">{{fenceError}}</p></el-popover><el-button size="small" :icon="Crosshair" aria-label="显示全部车辆位置" @click="focusMap"/></div>
   </div>
   <aside v-if="detailOpen&&selected" class="monitor-detail" aria-label="车辆详情"><header class="monitor-detail-head"><h3>车辆详情</h3><el-button text :icon="X" aria-label="关闭车辆详情" @click="detailOpen=false;tab='state'"/></header><div class="monitor-detail-body">
    <div class="monitor-identity"><div><h3>{{selected.name}}</h3><p>{{selected.unifiedCode||selected.businessNo}}</p></div><el-tag size="small" :type="selected.health.stale?'info':'primary'">{{monitorStates[selected.health.state]}}</el-tag></div>
    <el-tabs v-model="tab"><el-tab-pane label="实时状态" name="state"/><el-tab-pane v-if="can(user,'operation:trajectory:read')" label="历史轨迹" name="track"/><el-tab-pane v-if="can(user,'operation:record:read')" label="运行记录" name="records"/></el-tabs>
    <template v-if="tab==='state'"><dl class="monitor-data"><div><dt>{{selected.health.stale?'最后上报速度':'当前速度'}}</dt><dd>{{selected.realtimeStatus?.speed??'—'}} <small>km/h</small></dd></div><div><dt>{{selected.health.stale?'最后上报电量':'剩余电量'}}</dt><dd>{{selected.realtimeStatus?.battery??'—'}}%</dd></div><div><dt>{{selected.health.stale?'最后驾驶模式':'驾驶模式'}}</dt><dd>{{drivingMode(selected.realtimeStatus?.autonomousState)}}</dd></div><div><dt>当日上报里程</dt><dd>{{selected.realtimeStatus?.mileageToday??'—'}} km</dd></div><div><dt>定位时间</dt><dd>{{monitorTime(selected.realtimeStatus?.locationTime)}}</dd></div><div><dt>最后上报</dt><dd>{{ageText(selected.health.heartbeatAge)}}</dd></div></dl>
     <h4 class="monitor-detail-section">许可与范围</h4><dl class="monitor-data"><div><dt>许可状态</dt><dd>{{permitStates[selected.permit?.status]??'未登记许可'}}</dd></div><div><dt>许可类型</dt><dd>{{permitTypes[selected.permit?.licenseType]??'—'}}</dd></div><div class="wide"><dt>通行区域</dt><dd>{{selected.regions.map((r:any)=>r.name).join('、')||'未登记通行边界'}}</dd></div><div><dt>允许时段</dt><dd>{{selected.permit?.conditions.allowedHours||'未登记'}}</dd></div><div><dt>许可限速</dt><dd>{{selected.permit?.conditions.speedLimit??'—'}} km/h</dd></div><div class="wide"><dt>有效期至</dt><dd>{{admissionDate(selected.permit?.expiresAt)}}</dd></div></dl>
     <div class="monitor-check" :class="{warning:!['VALID','EXPIRING'].includes(selected.permit?.status)||selected.scopeStatus!=='INSIDE'}">{{!['VALID','EXPIRING'].includes(selected.permit?.status)?'当前许可不可用于运行，请核查':selected.scopeStatus==='UNKNOWN'?'定位与状态已陈旧，当前位置待核查':selected.scopeStatus==='UNREGISTERED'?'许可未登记边界，范围暂不能核验':selected.scopeStatus==='OUTSIDE'?'当前位置在许可范围外，请核查':'当前位于许可通行范围内'}}</div>
     <h4 class="monitor-detail-section">责任安全员</h4><p v-if="!selected.operators.length" class="monitor-note">{{can(user,'archive:qualification:read')?'尚未关联安全员':'无人员查看权限'}}</p><p v-for="o in selected.operators" :key="o.id" class="monitor-note">{{o.name}} / {{o.phone||'未登记联系方式'}} · {{o.onDuty?'已登记值守':'未登记值守'}}</p>
     <h4 class="monitor-detail-section">当前异常</h4><p v-if="!selected.abnormal" class="monitor-check">暂无待核查异常</p><div v-for="(i,index) in displayIssues" :key="index" class="monitor-alert">{{i.title}}</div><div v-for="a in selected.alerts" :key="a.id" class="monitor-alert"><strong>{{a.title}}</strong><br>{{monitorTime(a.occurredAt)}}<br><el-button v-if="hasAlertPermission" link type="primary" @click="event(a.id)">查看事件</el-button></div>
    </template>
    <template v-else-if="tab==='track'"><div class="monitor-track-query"><el-date-picker v-model="trackRange" type="datetimerange" value-format="YYYY-MM-DDTHH:mm:ssZ" start-placeholder="开始时间" end-placeholder="结束时间" aria-label="轨迹时间范围"/><el-button :loading="trackLoading" @click="loadTrack">查询轨迹</el-button></div><p v-if="trackError" class="monitor-alert" role="alert">{{trackError}}</p><p v-else-if="!trackLoading&&!track.length" class="monitor-note">所选时段暂无轨迹，可调整时间范围</p><dl class="monitor-data"><div><dt>轨迹点</dt><dd>{{stats.count}}</dd></div><div><dt>最高速度</dt><dd>{{stats.max??'—'}} km/h</dd></div></dl><div class="monitor-replay"><el-button size="small" :disabled="track.length<2" type="primary" @click="play">{{paused?'继续':'回放'}}</el-button><el-button size="small" :disabled="!playing||paused" @click="pause">暂停</el-button><el-button size="small" :disabled="!playing" @click="stop">复位</el-button></div><p class="monitor-note">显示原始上报轨迹；相邻数据间隔超过5分钟时分段显示。</p><p v-if="trackTruncated" class="monitor-alert">轨迹超过5000点，请缩小时间范围查看完整数据</p></template>
    <template v-else><p v-if="recordError" class="monitor-alert" role="alert">{{recordError}}<el-button link @click="loadRecords">重试</el-button></p><el-skeleton v-else-if="recordLoading" :rows="5"/><p v-else-if="!records.length" class="monitor-note">暂无运行记录</p><div v-for="r in records" :key="r.id" class="monitor-record"><strong>{{r.businessNo}}</strong><span>{{monitorTime(r.startedAt)}} — {{r.endedAt?monitorTime(r.endedAt):'运行中'}}</span><span>{{r.mileage}} km · {{r.region?.name||'未关联区域'}}</span><el-button v-if="can(user,'operation:trajectory:read')" link type="primary" @click="recordTrack(r)">查看本次轨迹</el-button></div><el-pagination v-if="recordTotal>10" small v-model:current-page="recordPage" :page-size="10" :total="recordTotal" layout="prev,pager,next"/></template>
   </div><footer class="monitor-detail-footer"><el-button v-if="can(user,'archive:vehicle:read')" @click="archiveOpen=true">查看档案</el-button><el-button v-if="selected.permit&&can(user,'admission:license:read')" type="primary" @click="permitOpen=true">查看许可</el-button></footer></aside>
  </div>
 </section>
 <VehicleDetailDrawer v-model="archiveOpen" :vehicle-id="selectedId"/><PermitDetailDrawer v-model="permitOpen" :license-id="selected?.permit?.id??''"/>
</section>
</template>
